const CSS=".xhs{box-sizing:border-box;width:100%;height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;padding:10px;color:var(--ink);font:13px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.xhs *{box-sizing:border-box}\n.xhs.compact{padding:8px;gap:5px}\n.xhs :focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.sec{display:flex;flex-direction:column;gap:6px;min-height:0;min-width:0}\n.compact .sec{gap:5px}\n.form{overflow-y:auto}\n.res{overflow:hidden}\n.m-tabs .sec{flex:1}\n.m-cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}\n.m-stack{overflow-y:auto}\n.m-stack .form{flex:none;overflow:visible}\n.m-stack .res{flex:1;min-height:110px}\n.tabs{display:flex;gap:4px;flex:none}\n.tab{flex:1;min-height:26px;padding:0 6px;border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:8px;font:inherit;font-size:12px;cursor:pointer}\n.tab[aria-selected=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lab{font-size:12px;color:var(--muted)}\n.row2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}\n.compact .row2{gap:5px}\n.in{display:block;width:100%;min-width:0;min-height:32px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px}\n.compact .in{min-height:28px;padding:3px 7px}\n.compact .sel{font-size:12px;padding:3px 4px}\n.in::placeholder{color:var(--muted)}\ntextarea.in{resize:none;line-height:1.4}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{min-height:28px;padding:3px 11px;border:1px solid var(--line);border-radius:14px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:12.5px;cursor:pointer}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:60