var TONES=['种草','干货','搞笑','共鸣','悬念','专业'];
var COUNTS=[3,5,8,10];
var LIMIT=20;
var NOTE_OFF='AI 生成暂未接入这张卡片，现在无法自动出标题。主题、人群、语气和数量已保存，接入后可直接使用；也可以先在「结果」里手动添加标题再修改。';

function cfgOf(s){
  var c=(s&&s.cfg)||{};
  var n=Number(c.count);
  return {
    topic:String(c.topic||''),
    audience:String(c.audience||''),
    tone:TONES.indexOf(c.tone)>=0?c.tone:TONES[0],
    count:COUNTS.indexOf(n)>=0?n:5
  };
}
function itemsOf(s){
  return s&&Array.isArray(s.items)?s.items:[];
}
function lenOf(t){
  return Array.from(String(t||'')).length;
}
function countText(t){
  var n=lenOf(t);
  return n>LIMIT?'⚠ 超出 '+(n-LIMIT)+' 字（'+n+'/'+LIMIT+'）':n+'/'+LIMIT+' 字';
}


function mount(ctx){
  const {root,el,state,ui,update,uid,redraw,size}=ctx;
  const cfg=cfgOf(state);
  const items=itemsOf(state);
  const d=ui.draft||(ui.draft={});
  const mode=(size==='3x3'||size==='3x6')?'tabs':(size==='6x3'?'cols':'stack');
  const compact=(size==='3x3'||size==='6x3');
  const tab=ui.tab==='res'?'res':'set';
  const fmap={};
  const rk=ui.restore;
  ui.restore=null;
  const topicVal=d.topic!==undefined?d.topic:cfg.topic;
  const audVal=d.audience!==undefined?d.audience:cfg.audience;

  function fail(e){
    ui.err='保存失败：'+(e&&e.message?e.message:'请稍后重试');
    redraw();
    return false;
  }
  function save(fn){
    ui.restore=ui.focus;
    return update(fn).catch(fail);
  }
  function act(fn){
    return function(){
      ui.focus=null;
      ui.err=null;
      ui.note=null;
      return fn();
    };
  }
  function saveCfg(patch){
    return save(function(s){
      var c=cfgOf(s);
      var next=Object.assign({},c,{
        topic:d.topic!==undefined?d.topic:c.topic,
        audience:d.audience!==undefined?d.audience:c.audience
      },patch||{});
      return Object.assign({},s,{cfg:next});
    });
  }
  function setText(id,v){
    return save(function(s){
      return Object.assign({},s,{items:itemsOf(s).map(function(i){
        return i.id===id?Object.assign({},i,{text:v}):i;
      })});
    });
  }
  function delItem(id){
    return save(function(s){
      return Object.assign({},s,{items:itemsOf(s).filter(function(i){return i.id!==id;})});
    });
  }
  function addItem(){
    var id=uid();
    ui.focus='it:'+id;
    return save(function(s){
      return Object.assign({},s,{items:[{id:id,text:''}].concat(itemsOf(s))});
    });
  }
  function generate(where){
    var t=String(d.topic!==undefined?d.topic:cfg.topic).trim();
    if(!t){
      ui.tab='set';
      ui.restore='topic';
      ui.note={where:'form',kind:'err',text:'⚠ 请先填写主题，再生成标题。'};
      redraw();
      return;
    }
    saveCfg().then(function(ok){
      if(ok){
        ui.note={where:where,kind:'info',text:NOTE_OFF};
        redraw();
      }
    });
  }
  function field(key,val,label,ph,o){
    var inp=el(o.multi?'textarea':'input',{
      class:'in','aria-label':label,
      onfocus:function(){ui.focus=key;},
      onblur:function(){ui.focus=null;},
      oninput:function(){o.input(inp.value);},
      onchange:function(){o.change(inp.value);},
      onkeydown:function(ev){
        if(ev.key==='Enter'&&!ev.isComposing){ev.preventDefault();inp.blur();}
      }
    });
    inp.value=val;
    inp.placeholder=ph;
    if(o.multi)inp.rows=2;
    fmap[key]=inp;
    return inp;
  }
  function chips(list,cur,label,onPick,fmt){
    return el('div',{class:'chips',role:'group','aria-label':label},
      ...list.map(function(v){
        var on=v===cur;
        return el('button',{type:'button',class:'chip'+(on?' on':''),'aria-pressed':String(on),
          onclick:act(function(){if(!on)onPick(v);})},fmt?fmt(v):v);
      }));
  }
  function select(label,list,cur,fmt,onPick){
    var s=el('select',{class:'in sel','aria-label':label,
      onchange:act(function(){onPick(s.value);})},
      ...list.map(function(v){return el('option',{value:String(v)},fmt(v));}));
    s.value=String(cur);
    return s;
  }
  function noteEl(where){
    var n=ui.note;
    if(!n||n.where!==where)return null;
    return el('div',{class:'note '+n.kind,role:'status'},n.text);
  }


  function formSec(){
    var topicIn=field('topic',topicVal,'主题',compact?'主题':'例如：新手露营装备清单',{
      input:function(v){d.topic=v;},
      change:function(v){
        d.topic=v;
        if(v!==cfg.topic)setTimeout(function(){saveCfg();},0);
      }
    });
    var audIn=field('audience',audVal,'想给谁看',compact?'给谁看':'例如：第一次露营的上班族',{
      input:function(v){d.audience=v;},
      change:function(v){
        d.audience=v;
        if(v!==cfg.audience)setTimeout(function(){saveCfg();},0);
      }
    });
    var body;
    if(compact){
      body=[
        topicIn,audIn,
        el('div',{class:'row2'},
          select('语气',TONES,cfg.tone,function(v){return '语气：'+v;},function(v){saveCfg({tone:v});}),
          select('数量',COUNTS,cfg.count,function(v){return '数量：'+v+' 个';},function(v){saveCfg({count:Number(v)});}))
      ];
    }else{
      body=[
        el('div',{class:'row2'},
          el('label',{class:'fld'},el('span',{class:'lab'},'主题'),topicIn),
          el('label',{class:'fld'},el('span',{class:'lab'},'想给谁看'),audIn)),
        el('div',{class:'fld'},el('span',{class:'lab'},'语气'),
          chips(TONES,cfg.tone,'语气',function(v){saveCfg({tone:v});})),
        el('div',{class:'fld'},el('span',{class:'lab'},'数量'),
          chips(COUNTS,cfg.count,'数量',function(v){saveCfg({count:v});},function(v){return v+' 个';}))
      ];
    }
    var gen=el('button',{type:'button',class:'primary',onclick:act(function(){generate('form');})},
      '生成 '+cfg.count+' 个标题');
    var note=noteEl('form');
    var tail=note||(size==='3x3'?null:el('div',{class:'hint'},'AI 生成暂未接入 · 设置自动保存'));
    return el('div',{class:'sec form'},...body,gen,tail);
  }

  function itemEl(it){
    var cnt=el('span',{class:'cnt'+(lenOf(it.text)>LIMIT?' over':'')},countText(it.text));
    var ta=field('it:'+it.id,it.text,'标题','输入标题',{
      multi:true,
      input:function(v){
        cnt.textContent=countText(v);
        cnt.className='cnt'+(lenOf(v)>LIMIT?' over':'');
      },
      change:function(v){
        if(v!==it.text)setTimeout(function(){setText(it.id,v);},0);
      }
    });
    return el('div',{class:'it'},ta,
      el('div',{class:'meta'},cnt,
        el('button',{type:'button',class:'lnk','aria-label':'删除这条标题',onclick:act(function(){delItem(it.id);})},'删除')));
  }

  function resSec(){
    var head=el('div',{class:'rh'},
      el('span',{class:'ttl'},'结果 · '+items.length+' 条'),
      items.length?el('button',{type:'button',class:'sm',onclick:act(function(){generate('res');})},'换一批'):null,
      el('button',{type:'button',class:'sm pri',onclick:act(addItem)},'＋ 添加'));
    var note=noteEl('res');
    var list=items.length
      ?el('div',{class:'list'},...items.map(itemEl))
      :el('div',{class:'list'},el('div',{class:'empty'},
        '还没有标题。AI 生成暂未接入，目前可点「＋ 添加」手动记录标题，再直接修改。'));
    return el('div',{class:'sec res'},head,note,list);
  }

  function tabbar(){
    function tb(id,text){
      return el('button',{type:'button',role:'tab',class:'tab','aria-selected':String(tab===id),
        onclick:act(function(){ui.tab=id;redraw();})},text);
    }
    return el('div',{class:'tabs',role:'tablist'},tb('set','设置'),tb('res','结果 '+items.length));
  }

  const kids=[];
  if(mode==='tabs')kids.push(tabbar());
  if(ui.err)kids.push(el('div',{class:'note err',role:'alert'},ui.err));
  if(mode==='tabs')kids.push(tab==='res'?resSec():formSec());
  else kids.push(formSec(),resSec());
  const wrap=el('div',{class:'xhs m-'+mode+(compact?' compact':'')},...kids);
  root.append(wrap);
  if(rk&&fmap[rk]){
    var f=fmap[rk];
    f.focus();
    try{var L=f.value.length;f.setSelectionRange(L,L);}catch(e){}
  }
}

