 async fetchSource(id){const r=await this.host.fetchData(id);if(r?.status!=='ok')throw Error(r?.errorCode||r?.message||'数据源获取失败');const d=r.data;if(d===null||typeof d!=='object'||Object.keys(d).length===0)throw Error('暂未获取到有效数据');return d;}
 async requestData(input){const r=await this.host.requestJson(input);if(r?.ok!==true||!(r.status>=200&&r.status<300))throw Error('HTTP '+(r?.status??'unknown'));if(r.data===null||r.data===undefined)throw Error('响应没有有效数据');return r.data;}
 render(){this.renderedContext=this.contextShape();this.colorListener=null;this.cleanup?.();this.cleanup=null;this.shadowRoot.replaceChildren();const style=document.createElement('style');style.textContent=COLOR_CSS+INFRA_CSS+CSS;this.shadowRoot.append(style);this.dataset.surface=this.host.ctx.surface;const root=document.createElement('section');root.className='card';root.dataset.size=this.host.ctx.size;this.shadowRoot.append(root);
 const el=(tag,attrs,...children)=>{const svg=['svg','path','circle','rect','ellipse','g','line','polyline','polygon','text','tspan','defs','linearGradient','radialGradient','stop','clipPath','mask','use','symbol'];const n=svg.includes(tag)?document.createElementNS('http://www.w3.org/2000/svg',tag):document.createElement(tag);for(const[k,v]of Object.entries(attrs||{})){if(k.startsWith('on')&&typeof v==='function')n.addEventListener(k.slice(2).toLowerCase(),v);else if(k==='value')n.value=v??'';else if(['checked','disabled','selected','required','multiple'].includes(k))n[k]=Boolean(v);else if(k==='style'&&v&&typeof v==='object')Object.assign(n.style,v);else if(v!==null&&v!==undefined)n.setAttribute(k,String(v));}for(const c of children.flat(Infinity))if(c!==null&&c!==undefined&&c!==false)n.append(typeof c==='object'?c:document.createTextNode(String(c)));return n;};
